import type {
  LightRaysOriginSpec,
  LightRaysProps,
  LightRaysSettings,
  LightRaysVec3,
  RaysOrigin,
} from './types';

export const PIXEL_BUDGET = 2.4e6;
export const MAX_PULSES = 4;

const ORIGINS: Record<RaysOrigin, LightRaysOriginSpec> = {
  'top-left': { anchor: [0, -0.2], dir: [0, 1] },
  'top-center': { anchor: [0.5, -0.2], dir: [0, 1] },
  'top-right': { anchor: [1, -0.2], dir: [0, 1] },
  left: { anchor: [-0.2, 0.5], dir: [1, 0] },
  right: { anchor: [1.2, 0.5], dir: [-1, 0] },
  'bottom-left': { anchor: [0, 1.2], dir: [0, -1] },
  'bottom-center': { anchor: [0.5, 1.2], dir: [0, -1] },
  'bottom-right': { anchor: [1, 1.2], dir: [0, -1] },
};

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

function parseColor(value: string | undefined): LightRaysVec3 | null {
  const text = String(value || '').trim();
  const hex = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(text);
  if (hex?.[1]) {
    const digits = hex[1];
    const full =
      digits.length === 3 ? digits.replace(/./g, (d) => d + d) : digits;
    return [
      Number.parseInt(full.slice(0, 2), 16) / 255,
      Number.parseInt(full.slice(2, 4), 16) / 255,
      Number.parseInt(full.slice(4, 6), 16) / 255,
    ];
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(text);
  if (rgb) {
    const channel = (part: string | undefined) =>
      clamp(Number.parseFloat(part ?? '0') / 255, 0, 1);
    return [channel(rgb[1]), channel(rgb[2]), channel(rgb[3])];
  }
  return null;
}

export const smoother = (t: number) => {
  const x = clamp(t, 0, 1);
  return x * x * x * (x * (x * 6 - 15) + 10);
};

export function resolveSettings(props: LightRaysProps): LightRaysSettings {
  return {
    origin: ORIGINS[props.raysOrigin ?? 'top-center'] ?? ORIGINS['top-center'],
    color: parseColor(props.raysColor ?? '#ffffff') ?? [1, 1, 1],
    speed: Math.max(0, props.raysSpeed ?? 1),
    spread: Math.max(0.001, props.lightSpread ?? 0.5),
    length: Math.max(0.01, props.rayLength ?? 3),
    density: clamp(props.rayDensity ?? 1, 0.1, 6),
    tilt: (clamp(props.tilt ?? 0, -90, 90) * Math.PI) / 180,
    sharpness: clamp(props.raySharpness ?? 0.35, 0, 1),
    glow: Math.max(0, props.glow ?? 0.6),
    haze: clamp(props.haze ?? 0.25, 0, 1),
    atmosphere: clamp(props.atmosphere ?? 1, 0, 1),
    intensity: Math.max(0, props.intensity ?? 1),
    pulsating: props.pulsating ?? false,
    fade: Math.max(0.01, props.fadeDistance ?? 1),
    saturation: Math.max(0, props.saturation ?? 1),
    follow: props.followMouse ?? true,
    influence: clamp(props.mouseInfluence ?? 0.1, 0, 1),
    cursorShadow: props.cursorShadow ?? true,
    clickPulse: props.clickPulse ?? true,
    noise: clamp(props.noiseAmount ?? 0, 0, 1),
    distortion: props.distortion ?? 0,
    intro: props.intro ?? true,
    light: props.lightMode ?? false,
    opacity: clamp(props.opacity ?? 1, 0, 1),
    maxRatio: clamp(props.maxDevicePixelRatio ?? 2, 0.5, 3),
  };
}

import { MAX_PULSES, PIXEL_BUDGET, clamp, smoother } from './light-rays-config';
import { FRAGMENT, VERTEX } from './light-rays-shaders';
import type { LightRaysEngine, LightRaysEngineOptions } from './types';

function compile(gl: WebGL2RenderingContext, type: number, source: string) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    console.error(gl.getShaderInfoLog(shader));
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

function link(gl: WebGL2RenderingContext) {
  const vertex = compile(gl, gl.VERTEX_SHADER, VERTEX);
  const fragment = compile(gl, gl.FRAGMENT_SHADER, FRAGMENT);
  const program = vertex && fragment ? gl.createProgram() : null;
  if (!vertex || !fragment || !program) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    return null;
  }
  gl.attachShader(program, vertex);
  gl.attachShader(program, fragment);
  gl.linkProgram(program);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    console.error(gl.getProgramInfoLog(program));
    gl.deleteProgram(program);
    return null;
  }
  const uniforms = new Map<string, WebGLUniformLocation | null>();
  const count: number = gl.getProgramParameter(program, gl.ACTIVE_UNIFORMS);
  for (let index = 0; index < count; index++) {
    const info = gl.getActiveUniform(program, index);
    if (info) {
      uniforms.set(
        info.name.replace(/\[0\]$/, ''),
        gl.getUniformLocation(program, info.name),
      );
    }
  }
  return { program, uniforms };
}

/**
 * Draws the volumetric rays into `canvas` with raw WebGL2.
 * Returns null when WebGL2 or the shader is unavailable.
 */
export function createLightRaysEngine(
  container: HTMLElement,
  canvas: HTMLCanvasElement,
  { getSettings, reducedMotion, playIntro }: LightRaysEngineOptions,
): LightRaysEngine | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    premultipliedAlpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    powerPreference: 'high-performance',
  });
  const shader = gl ? link(gl) : null;
  if (!gl || !shader) return null;
  const loc = (name: string) => shader.uniforms.get(name) ?? null;

  const vao = gl.createVertexArray();
  const size = { width: 1, height: 1, ratio: 1 };
  const pointer = { x: 0.5, y: 0.5, inside: false, seen: false };
  const aim = { x: 0.5, y: 0.5 };
  const shade = { x: 0.5, y: 0.5, presence: 0 };
  const pulses: { age: number }[] = [];
  const pulseData = new Float32Array(MAX_PULSES * 4);
  let time = 0;
  let opening = getSettings().intro && !reducedMotion && playIntro ? 0 : 1;
  let raf = 0;
  let last = 0;
  let visible = true;
  let pageVisible = document.visibilityState !== 'hidden';
  let lost = false;

  const resize = () => {
    const s = getSettings();
    const rect = container.getBoundingClientRect();
    const cssWidth = Math.max(1, rect.width);
    const cssHeight = Math.max(1, rect.height);
    const detail = s.density * (0.35 + 0.65 * s.sharpness);
    const sampling = Math.max(
      clamp(0.35 + 0.3 * detail, 0.5, 2),
      s.noise > 0 ? 1 : 0,
    );
    const ratio = Math.min(
      window.devicePixelRatio || 1,
      s.maxRatio,
      sampling,
      Math.sqrt(PIXEL_BUDGET / (cssWidth * cssHeight)),
    );
    const width = Math.max(1, Math.round(cssWidth * ratio));
    const height = Math.max(1, Math.round(cssHeight * ratio));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    size.width = cssWidth;
    size.height = cssHeight;
    size.ratio = width / cssWidth;
  };

  const frame = (now: number) => {
    raf = 0;
    if (lost) return;
    const s = getSettings();
    const dt = clamp((now - last) / 1000 || 0, 0, 0.05);
    last = Math.max(last, now);
    time += dt * s.speed * (reducedMotion ? 0.35 : 1);
    if (opening < 1) opening = Math.min(1, opening + dt / 1.8);

    const steer = 1 - Math.exp(-dt / 0.2);
    const aimX = s.follow && pointer.seen ? pointer.x : 0.5;
    const aimY = s.follow && pointer.seen ? pointer.y : 0.5;
    aim.x += (aimX - aim.x) * steer;
    aim.y += (aimY - aim.y) * steer;
    const glide = 1 - Math.exp(-dt / 0.08);
    shade.x += (pointer.x - shade.x) * glide;
    shade.y += (pointer.y - shade.y) * glide;
    const shading = pointer.inside && s.cursorShadow && !reducedMotion;
    shade.presence +=
      ((shading ? 1 : 0) - shade.presence) *
      (1 - Math.exp(-dt / (shading ? 0.25 : 0.5)));

    for (let index = pulses.length - 1; index >= 0; index--) {
      const pulse = pulses[index]!;
      pulse.age += dt;
      if (pulse.age >= 2) pulses.splice(index, 1);
    }
    pulseData.fill(0);
    for (const [index, pulse] of pulses.entries()) {
      const t = pulse.age;
      pulseData[index * 4] = 0.05 + t * 1.05;
      pulseData[index * 4 + 1] = 0.14 + t * 0.14;
      pulseData[index * 4 + 2] =
        0.9 * smoother(t / 0.15) * (1 - smoother(t / 2));
    }

    const width = size.width;
    const height = size.height;
    const sourceX = s.origin.anchor[0] * width;
    const sourceY = s.origin.anchor[1] * height;
    const cos = Math.cos(s.tilt);
    const sin = Math.sin(s.tilt);
    let dirX = s.origin.dir[0] * cos - s.origin.dir[1] * sin;
    let dirY = s.origin.dir[0] * sin + s.origin.dir[1] * cos;
    if (s.follow && s.influence > 0) {
      const mx = aim.x * width - sourceX;
      const my = aim.y * height - sourceY;
      const ml = Math.hypot(mx, my) || 1;
      const bx = dirX + (mx / ml - dirX) * s.influence;
      const by = dirY + (my / ml - dirY) * s.influence;
      const bl = Math.hypot(bx, by) || 1;
      dirX = bx / bl;
      dirY = by / bl;
    }
    const eased = 1 - Math.pow(1 - opening, 3);

    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.clearColor(0, 0, 0, 0);
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.useProgram(shader.program);
    gl.bindVertexArray(vao);
    gl.uniform2f(loc('uResolution'), canvas.width, canvas.height);
    gl.uniform1f(loc('uScale'), size.ratio);
    gl.uniform1f(loc('uTime'), time);
    gl.uniform2f(loc('uSource'), sourceX, sourceY);
    gl.uniform2f(loc('uAim'), dirX, dirY);
    gl.uniform1f(loc('uReach'), Math.max(width, height));
    gl.uniform3f(loc('uColor'), s.color[0], s.color[1], s.color[2]);
    gl.uniform1f(loc('uSpread'), s.spread);
    gl.uniform1f(loc('uLength'), s.length);
    gl.uniform1f(loc('uFade'), s.fade);
    gl.uniform1f(loc('uSaturation'), s.saturation);
    gl.uniform1f(loc('uPulsating'), s.pulsating ? 1 : 0);
    gl.uniform1f(loc('uNoise'), s.noise);
    gl.uniform1f(loc('uDistortion'), s.distortion);
    gl.uniform1f(loc('uDensity'), s.density);
    gl.uniform1f(loc('uSharpness'), s.sharpness);
    gl.uniform1f(loc('uGlow'), s.glow);
    gl.uniform1f(loc('uHaze'), s.haze);
    gl.uniform1f(loc('uAtmosphere'), s.atmosphere);
    gl.uniform1f(loc('uIntensity'), s.intensity);
    gl.uniform4f(
      loc('uShadow'),
      shade.x * width,
      shade.y * height,
      shade.presence,
      16,
    );
    gl.uniform4fv(loc('uPulses'), pulseData);
    gl.uniform2f(loc('uIntro'), eased * 2.6, smoother(opening / 0.5));
    gl.uniform1f(loc('uLight'), s.light ? 1 : 0);
    gl.uniform1f(loc('uOpacity'), s.opacity);
    gl.drawArrays(gl.TRIANGLES, 0, 3);

    const settling =
      Math.abs(aim.x - aimX) > 1e-4 ||
      Math.abs(aim.y - aimY) > 1e-4 ||
      (shade.presence > 1e-3 &&
        Math.abs(shade.x - pointer.x) + Math.abs(shade.y - pointer.y) > 1e-4) ||
      Math.abs((shading ? 1 : 0) - shade.presence) > 1e-3 ||
      pulses.length > 0;
    const busy = s.speed > 0 || opening < 1 || settling;
    if (busy && visible && pageVisible) raf = requestAnimationFrame(frame);
  };

  const wake = () => {
    if (raf || lost || !visible || !pageVisible) return;
    last = performance.now();
    raf = requestAnimationFrame(frame);
  };

  const locate = (event: PointerEvent) => {
    const rect = container.getBoundingClientRect();
    return {
      x: (event.clientX - rect.left) / Math.max(1, rect.width),
      y: (event.clientY - rect.top) / Math.max(1, rect.height),
      inside:
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom,
    };
  };

  const leave = () => {
    pointer.inside = false;
    wake();
  };

  resize();
  wake();

  return {
    refresh() {
      resize();
      wake();
    },
    setVisible(next) {
      visible = next;
      wake();
    },
    setPageVisible(next) {
      pageVisible = next;
      wake();
    },
    pointerMove(event) {
      const spot = locate(event);
      if (!pointer.inside && spot.inside) {
        shade.x = spot.x;
        shade.y = spot.y;
      }
      pointer.x = spot.x;
      pointer.y = spot.y;
      pointer.inside = spot.inside;
      pointer.seen = true;
      wake();
    },
    pointerDown(event) {
      const spot = locate(event);
      if (!spot.inside || !getSettings().clickPulse || reducedMotion) return;
      pulses.push({ age: 0 });
      if (pulses.length > MAX_PULSES) pulses.shift();
      wake();
    },
    pointerUp(event) {
      if (event.pointerType !== 'mouse') leave();
    },
    leave,
    dispose() {
      lost = true;
      cancelAnimationFrame(raf);
      raf = 0;
      if (!gl.isContextLost()) {
        gl.deleteVertexArray(vao);
        gl.deleteProgram(shader.program);
      }
    },
  };
}

import { MAX_PULSES } from './light-rays-config';

export const VERTEX = `#version 300 es
const vec2 corners[3] = vec2[3](vec2(-1.0, -1.0), vec2(3.0, -1.0), vec2(-1.0, 3.0));
void main() {
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}`;

export const FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uScale;
uniform float uTime;
uniform vec2 uSource;
uniform vec2 uAim;
uniform float uReach;
uniform vec3 uColor;
uniform float uSpread;
uniform float uLength;
uniform float uFade;
uniform float uSaturation;
uniform float uPulsating;
uniform float uNoise;
uniform float uDistortion;
uniform float uDensity;
uniform float uSharpness;
uniform float uGlow;
uniform float uHaze;
uniform float uAtmosphere;
uniform float uIntensity;
uniform vec4 uShadow;
uniform vec4 uPulses[${MAX_PULSES}];
uniform vec2 uIntro;
uniform float uLight;
uniform float uOpacity;
out vec4 fragColor;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float valueNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = p - i;
  vec2 w = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), w.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), w.x), w.y);
}

float shape(float strength, float width) {
  float edge = max(mix(0.5, 0.08, uSharpness), width);
  return mix(strength, smoothstep(0.62 - edge, 0.62 + edge, strength), uSharpness);
}

void main() {
  vec2 coord = vec2(gl_FragCoord.x, uResolution.y - gl_FragCoord.y) / uScale;
  vec2 delta = coord - uSource;
  float distance = length(delta);
  vec2 dir = delta / max(distance, 1e-4);
  float cosAngle = dot(dir, uAim);
  float angle = cosAngle + uDistortion * sin(uTime * 2.0 + distance * 0.02) * 0.2;
  float slope = fwidth(angle);
  float depth = distance / uReach;

  float source = exp(-depth * depth * 9.0) * 0.9 + exp(-depth * 3.2) * 0.25;
  float glowLight = uGlow * source * smoothstep(-0.2, 0.6, cosAngle);
  float spread = pow(max(angle, 0.0), 1.0 / uSpread);
  float lengthFalloff = clamp(1.0 - distance / (uReach * uLength), 0.0, 1.0);
  float fadeFalloff = clamp(1.0 - distance / (uReach * uFade), 0.5, 1.0);
  float envelope = spread * lengthFalloff * fadeFalloff;
  float reveal = uIntensity * uIntro.y * (1.0 - smoothstep(uIntro.x - 0.35, uIntro.x, depth));
  if ((envelope * 1.6 + glowLight) * reveal < 0.0015) {
    fragColor = vec4(0.0);
    return;
  }

  float phaseA = angle * 36.2214 * uDensity + uTime * 1.5;
  float phaseB = -angle * 21.11349 * uDensity + uTime * 1.5;
  float phaseC = angle * 22.3991 * uDensity + uTime * 1.1;
  float phaseD = -angle * 18.0234 * uDensity + uTime * 1.1;
  float strengthA = clamp(0.75 + 0.15 * sin(phaseA) + 0.2 * cos(phaseB), 0.0, 1.0);
  float strengthB = clamp(0.75 + 0.15 * sin(phaseC) + 0.2 * cos(phaseD), 0.0, 1.0);
  float widthA = abs(0.15 * 36.2214 * cos(phaseA) + 0.2 * 21.11349 * sin(phaseB)) * uDensity * slope;
  float widthB = abs(0.15 * 22.3991 * cos(phaseC) + 0.2 * 18.0234 * sin(phaseD)) * uDensity * slope;
  float pulseA = uPulsating > 0.5 ? 0.8 + 0.2 * sin(uTime * 4.5) : 1.0;
  float pulseB = uPulsating > 0.5 ? 0.8 + 0.2 * sin(uTime * 3.3) : 1.0;
  float rayLight = envelope * (0.5 * shape(strengthA, widthA) * pulseA + 0.4 * shape(strengthB, widthB) * pulseB);

  if (uHaze > 0.0) {
    float around = atan(uAim.x * dir.y - uAim.y * dir.x, cosAngle);
    vec2 drift = vec2(around * 2.2 + uTime * 0.035, depth * 2.6 - uTime * 0.11);
    float fog = 0.65 * valueNoise(drift * vec2(3.0, 1.0)) + 0.35 * valueNoise(drift * vec2(7.0, 2.3) + 4.1);
    rayLight *= mix(1.0, 0.25 + 1.2 * fog, uHaze);
  }

  if (uShadow.z > 0.0) {
    vec2 toCursor = uShadow.xy - uSource;
    float cursorDistance = length(toCursor);
    float along = dot(delta, toCursor) / max(cursorDistance * cursorDistance, 1e-4);
    float side = abs(delta.x * toCursor.y - delta.y * toCursor.x) / max(cursorDistance, 1e-4);
    float trail = max(along - 1.0, 0.0);
    float width = uShadow.w * along + 0.22 * trail * cursorDistance;
    float behind = smoothstep(0.97, 1.25, along) * exp(-trail * 1.1);
    float shade = (1.0 - smoothstep(width * 0.3, width * 1.6, side)) * behind;
    rayLight *= 1.0 - uShadow.z * 0.62 * shade;
  }

  float boost = 0.0;
  for (int i = 0; i < ${MAX_PULSES}; i++) {
    vec4 wave = uPulses[i];
    if (wave.z <= 0.0) continue;
    float x = (depth - wave.x) / wave.y;
    boost += wave.z * exp(-x * x);
  }
  float light = (rayLight * (1.0 + boost) + glowLight) * reveal;

  if (uNoise > 0.0) {
    float n = fract(sin(dot(coord * 0.02 + uTime * 0.1, vec2(12.9898, 78.233))) * 43758.5453123);
    light *= 1.0 - uNoise + uNoise * n;
  }

  float near = clamp(1.2 - distance / (uResolution.y / uScale), 0.0, 1.0);
  vec3 tint = mix(vec3(0.9), vec3(0.1, 0.3, 0.5) + near * vec3(0.8, 0.6, 0.5), uAtmosphere);
  float gray = dot(tint, vec3(0.299, 0.587, 0.114));
  vec3 hue = max(mix(vec3(gray), tint, uSaturation), 0.0) * uColor;

  float grain = (fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715)))) - 0.5) / 255.0;
  if (uLight > 0.5) {
    vec3 color = hue * light;
    float energy = max(color.r, max(color.g, color.b));
    vec3 tone = clamp(1.0 - (1.0 - hue / max(max(hue.r, max(hue.g, hue.b)), 1e-4)) * 1.8, 0.0, 1.0);
    float warm = clamp((min(tone.r, tone.g) - tone.b) * 2.0, 0.0, 1.0);
    vec3 ink = tone * (mix(0.66, 0.94, warm) - 0.1 * smoothstep(0.4, 1.2, energy));
    float density = clamp(0.82 * (1.0 - exp(-1.5 * energy * energy)) * uOpacity + grain, 0.0, 1.0);
    fragColor = vec4(ink * density, density);
    return;
  }
  float level = light < 0.75 ? light : 0.75 + 0.25 * (1.0 - exp(-(light - 0.75) / 0.25));
  float top = max(hue.r, max(hue.g, hue.b));
  hue = mix(hue, vec3(top), smoothstep(0.8, 1.0, level) * 0.45);
  vec3 shown = clamp(hue * level, 0.0, 1.0) * level;
  fragColor = vec4(clamp(shown + grain, 0.0, level) * uOpacity, level * uOpacity);
}`;

export type RaysOrigin =
  | 'top-center'
  | 'top-left'
  | 'top-right'
  | 'left'
  | 'right'
  | 'bottom-center'
  | 'bottom-left'
  | 'bottom-right';

export interface LightRaysProps {
  /** Where the light comes from. */
  raysOrigin?: RaysOrigin;
  /** Color of the light. */
  raysColor?: string;
  /** Animation speed. 0 freezes the rays. */
  raysSpeed?: number;
  /** How wide the beam opens. Lower values give a tight spotlight. */
  lightSpread?: number;
  /** How far the rays reach, in container widths. */
  rayLength?: number;
  /** How many separate shafts the beam splits into. */
  rayDensity?: number;
  /** Turns the beam by this many degrees. */
  tilt?: number;
  /** How crisp the edges of the shafts are, from 0 to 1. */
  raySharpness?: number;
  /** Brightness of the glow around the light source. */
  glow?: number;
  /** Drifting haze that breaks the shafts up, from 0 to 1. */
  haze?: number;
  /** How much the light cools toward blue as it travels, from 0 to 1. */
  atmosphere?: number;
  /** Overall brightness of the light. */
  intensity?: number;
  /** The rays slowly breathe brighter and dimmer. */
  pulsating?: boolean;
  /** How far the rays travel before they dim, in container widths. */
  fadeDistance?: number;
  /** Color saturation of the light. */
  saturation?: number;
  /** The beam turns toward the cursor. */
  followMouse?: boolean;
  /** How far the beam turns toward the cursor, from 0 to 1. */
  mouseInfluence?: number;
  /** The cursor blocks the light and casts a soft shadow down the rays. */
  cursorShadow?: boolean;
  /** Clicking sends a wave of light down the rays. */
  clickPulse?: boolean;
  /** Film grain over the rays, from 0 to 1. */
  noiseAmount?: number;
  /** Makes the rays waver as if seen through heat. */
  distortion?: number;
  /** The rays grow out from the source on mount. */
  intro?: boolean;
  /** Prints the light as soft colored ink so it sits on light pages. */
  lightMode?: boolean;
  /** Overall opacity, from 0 to 1. */
  opacity?: number;
  /** Highest pixel ratio the canvas renders at. */
  maxDevicePixelRatio?: number;
  class?: string;
}

export type LightRaysVec2 = [number, number];
export type LightRaysVec3 = [number, number, number];

export interface LightRaysOriginSpec {
  anchor: LightRaysVec2;
  dir: LightRaysVec2;
}

export interface LightRaysSettings {
  origin: LightRaysOriginSpec;
  color: LightRaysVec3;
  speed: number;
  spread: number;
  length: number;
  density: number;
  tilt: number;
  sharpness: number;
  glow: number;
  haze: number;
  atmosphere: number;
  intensity: number;
  pulsating: boolean;
  fade: number;
  saturation: number;
  follow: boolean;
  influence: number;
  cursorShadow: boolean;
  clickPulse: boolean;
  noise: number;
  distortion: number;
  intro: boolean;
  light: boolean;
  opacity: number;
  maxRatio: number;
}

export interface LightRaysEngineOptions {
  getSettings: () => LightRaysSettings;
  reducedMotion: boolean;
  /** Play the grow-in intro (false after a context restore). */
  playIntro: boolean;
}

export interface LightRaysEngine {
  refresh: () => void;
  setVisible: (visible: boolean) => void;
  setPageVisible: (visible: boolean) => void;
  pointerMove: (event: PointerEvent) => void;
  pointerDown: (event: PointerEvent) => void;
  pointerUp: (event: PointerEvent) => void;
  leave: () => void;
  dispose: () => void;
}
